import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const root = path.dirname(fileURLToPath(import.meta.url))
const escape = value => String(value).replace(/[&<>"']/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[character])
const chip = (label, selected = false, danger = false) => `<span class="chip${selected ? ' selected' : ''}${danger ? ' danger' : ''}">${escape(label)}</span>`
const chips = labels => `<div class="chips">${labels.map(label => chip(label)).join('')}</div>`
const notice = (title, text) => `<div class="notice"><strong>${escape(title)}</strong><p>${escape(text)}</p></div>`
const card = (title, body) => `<section class="card"><h2>${escape(title)}</h2>${body}</section>`
const board = () => `<div class="board">${['Q', 'W', 'E', 'R', 'T', 'Y', 'A', 'S', 'D', 'F', 'G', 'H'].map((key, index) => `<div class="key${index === 2 ? ' focused' : ''}"><small>Base</small><b>${key.toLowerCase()}${key}</b><span>ˬ ˬ</span><small>Lower · &amp;trans</small></div>`).join('')}</div><p class="muted">Synthetic 12-key fixture · click a firmware row to edit that layer.</p>`
const layerRows = (names = ['Base', 'Lower', 'Raise']) => `<table class="layer-rows"><thead><tr><th>Layer</th><th>Firmware actions</th></tr></thead><tbody>${names.map((name, index) => `<tr><th>${index} · ${name}</th><td>${chip('Duplicate')} ${chip(index === 0 ? 'Move · fixed' : 'Move')}</td></tr>`).join('')}</tbody></table>`
const firmwareLayers = () => card('Expanded layer table · Stack off', `<p class="eyebrow">Demo or verified Clipboard source</p>${layerRows()}<p>Duplicate appends “Lower copy”; keys and encoder turns are independent. References still target original layers. One firmware undo step.</p><h3>Move Lower — separate staged example</h3><div class="field">New layer position · 2 · Raise ▾</div><div class="actions">${chip('Apply move', true)}${chip('Cancel')}</div><p>Keyboard: Move → position → Apply. Or drag Move onto another Move control. Layer 0 stays fixed; moves change priority, not reference targets.</p><p class="muted">Focus follows the moved control. Cancel / Escape / unchanged position retain redo. Duplicate keeps focus on its source control.</p>`)

const layoutDiscovery = () => `<h2>Layout discovery · Clipboard / GitHub</h2>
<div class="columns"><div>
${card('1 · Optional catalog preview', `<p>No supplied geometry → editable binding-count rectangle. Open Layout discovery from firmware chrome on a clean document.</p><div class="field">Catalog JSON · version + entries<br>Reviewed resolved metadata; no bundled keyboard inventory</div>${chips(['Load catalog'])}<div class="field">Board / shield / revision · synthetic-board / no shield / 1 ▾<br>Candidate type · Transform ▾<br>Candidate label · second</div>${chips(['Resolved metadata and candidate labels', 'Preview layout'])}<p>Ambiguous unchosen layouts require an exact type/label. This never overrides firmware chosen declarations or fetches includes.</p>`)}
${notice('Unavailable — separate example states', 'Unknown board, invalid coordinates, unsupported includes or count mismatch: no candidate, Accept or Export. Keep the current editable rectangle or supply explicit layout JSON. Invalid catalog: correct the artifact and Load catalog again.')}
</div><div>
${card('2 · Candidate — separate preview state', `<p class="eyebrow">Inferred electrical arrangement — not measured physical geometry</p><div class="field">Document: example/config · main · config/example.keymap<br>Source revision: pinned head<br>Catalog revision: synthetic-v1 / content digest<br>Source: https://example.invalid/synthetic · immutable commit<br>Path: layout.dtsi · MIT · Synthetic example notice<br>Metadata SHA-256: content digest<br>Transform: second · zmk,matrix-transform · offsets 0, 0<br>Sensors: association unverified; firmware slots retained</div><p>Binding origins (schematic): 1 2 / 3 0. Binding order stays 0, 1, 2, 3. Scheme shows serialization slots, not electrical coordinates. Physical metadata is source-declared, not independently measured.</p><div class="field">☐ I acknowledge unverified firmware compatibility<br>and trust this catalog provenance</div><div class="actions">${chip('Accept layout · disabled until acknowledged')}${chip('Export layout JSON')}${chip('Cancel')}</div><p>Accept changes session geometry only. Export downloads validated JSON separately; it does not accept the preview or publish firmware/host work. No layout-file overwrite. Reload requires a new preview or explicit JSON.</p>`)}
${notice('Blocked / stale — separate states', 'Supplied layout JSON takes precedence; discovery cannot replace it. Dirty work, recovery or open drafts block capture. Changed source/document or stale GitHub proof refuses Accept and Export: close and reload/reopen. Cancel keeps layout, bindings and history.')}
</div></div>`

// Explicit viewport studies are schematics, not embedded application screenshots.
const definitionViewport = (title, body) => `<div class="viewport-study definition-viewport"><section class="definition-panel" aria-label="${escape(title)}"><h2>${escape(title)}</h2>${body}</section></div>`
// Both definition dialogs reuse these phase-1 schematic primitives.
const macroAction = (label, intent = 'outline', disabled = false) => `<span class="macro-action ${intent}${disabled ? ' disabled' : ''}">${escape(label)}</span>`
const macroStudy = () => `<section class="macro-design" aria-label="Macro editor design states">
<h2>Macros · compact editor controls</h2>
<p>Separate states, not simultaneous dialogs. Ordinary actions retain 30px chrome height; groups and fields are compact. Macros and Behaviors share the editor's light/dark control roles.</p>
<div class="columns"><div>
${card('Empty / populated list', `<p>No definitions: New macro or Text to sequence.</p><div class="macro-group"><p><code>&amp;greeting</code> · Greeting</p><div class="actions">${macroAction('Edit')}${macroAction('Use')}${macroAction('Delete', 'danger')}</div></div><div class="macro-group"><p><code>&amp;opaque</code> · Read-only: unsupported property</p><div class="actions">${macroAction('Edit', 'outline', true)}${macroAction('Use', 'outline', true)}${macroAction('Delete', 'danger')}</div><p>Delete refuses an unproven target.</p></div><div class="actions">${macroAction('New macro')}${macroAction('Text to sequence')}${macroAction('Close')}</div>`)}
${card('New / Edit · staged form', `<div class="macro-group"><div class="field">Macro label · greeting</div><div class="field">Display name · Greeting</div><div class="field">Parameter count · 0 ▾ (fixed on Edit)</div><p>Blank timing keeps firmware defaults; zero is explicit.</p><div class="field">Tap time (ms) · 0</div><div class="field">Wait time (ms) · 40</div></div><h3>Sequence</h3><div class="macro-group"><div class="field">Step 1 · Behavior binding ▾</div><div class="field"><code>&amp;kp A</code></div><div class="actions">${macroAction('Up', 'outline', true)}${macroAction('Down')}${macroAction('Remove', 'danger')}</div></div><div class="actions">${macroAction('Add step')}${macroAction('Preview changes')}${macroAction('Cancel')}</div><p>Fields, long labels and action rows wrap; the dialog owns vertical scroll. Source preview is still required.</p>`)}
</div><div>
${card('Text to sequence · separate state', `<div class="field">Text · A[]</div><p>☑ Use US QWERTY / ASCII mapping</p><pre>&amp;kp LS(A)\n&amp;kp LBKT\n&amp;kp RBKT</pre><div class="actions">${macroAction('Use generated sequence')}${macroAction('Cancel')}</div><p>New zero-parameter sequence, initial tap/wait 40 ms. Host language is not used.</p><div class="notice"><p>Invalid or unacknowledged: Use generated sequence is disabled. Printable ASCII, LF and TAB only; pasted CRLF is rejected. No partial conversion.</p>${macroAction('Use generated sequence', 'outline', true)}</div>`)}
${card('Invocation → source confirmation', `<div class="field">Destination · Key ▾</div><div class="field">Layer · 0 · base ▾</div><div class="field">Key position · 0 · &amp;kp A ▾</div><p>Parameterized macros expose inferred argument fields. Existing combos are also targets.</p><div class="actions">${macroAction('Preview binding')}${macroAction('Cancel')}</div><h3>Separate confirmation state</h3><p><code>&amp;kp A → &amp;greeting</code></p><pre>base { bindings = &lt;&amp;greeting &amp;kp B&gt;; };</pre><div class="actions">${macroAction('Confirm changes', 'accent')}${macroAction('Cancel')}</div><p>Full source is scrollable in the app. Confirmation is accent, not green publication. Eligible deletion uses the same preview boundary. Cancel leaves source/history unchanged.</p>`)}
</div></div></section>`
const definitionShells = () => `<section class="definition-shells">
<h2>Shared chrome → contained definition dialogs</h2>
<div class="firmware-chrome" aria-label="Firmware chrome">${chips(['Undo', 'Redo', 'Macros', 'Behaviors'])}</div>
<p>Compact outline launchers share the neighboring toolbar treatment. Separate 360×640 viewport studies below; each panel owns vertical scrolling, not the backdrop. Demo / verified Clipboard authoring only.</p>
<div class="columns"><div>
<div class="macro-design">${definitionViewport('Macros', `<div class="macro-group"><div class="field">Macro label · greeting<br>Display name · Greeting<br>Parameter count · 0</div><p>Existing parameter counts stay fixed.</p><div class="field">Tap time (ms) · 0<br>Wait time (ms) · 40</div></div><h3>Sequence</h3><p>Wait time sets the delay after subsequent events; it is not a standalone sleep.</p>${['&kp A', '&kp B', '&kp C'].map((binding, index) => `<div class="macro-group"><div class="field">Step ${index + 1} · Behavior binding<br>${escape(binding)}</div><div class="actions">${macroAction('Up', 'outline', index === 0)}${macroAction('Down', 'outline', index === 2)}${macroAction('Remove', 'danger')}</div></div>`).join('')}<div class="actions">${macroAction('Add step')}${macroAction('Preview changes')}${macroAction('Cancel')}</div>`)}</div>
<p class="study-caption">Macros · staged sequence, not applied. Scroll inside the panel to reach later steps, Preview changes and Cancel. Source confirmation is shown separately in the Macro states above.</p>
</div><div>
<div class="macro-design">${definitionViewport('Behaviors', `<p>Global definition: changes affect every reference. Invocation arguments stay per key, combo or encoder.</p><div class="macro-group"><div class="field">Behavior label · sticky<br>Behavior type · sticky-key</div><p>Node: sticky · #binding-cells: 1. Existing type, node name and cell count stay fixed.</p></div><p>Bare child references forward invocation arguments; do not add argument cells here.</p><div class="macro-group"><div class="field">Child 1 binding · &amp;kp</div></div><div class="macro-group"><div class="field">release-after-ms (required)<br>0</div><p>☐ quick-release</p><p>☐ lazy</p><p>☐ ignore-modifiers</p></div><div class="actions">${macroAction('Preview changes')}${macroAction('Cancel')}</div>`)}</div>
<p class="study-caption">Behaviors · same compact groups, fields, actions and scrolling shell as Macros. Global fields stay distinct from invocation operands; Preview changes precedes source-preview Apply changes.</p>
</div></div></section>`

const legendStrip = scrolled => `<div class="legend-detail"><p>${scrolled ? 'Scrolled right · Alt columns and Choose exposed' : 'Initial position · scroll the legend, not the page'}</p><div class="legend-scroll"${scrolled ? ' data-scroll-end' : ''} tabindex="0" role="region" aria-label="${scrolled ? 'Scrolled' : 'Initial'} legend detail"><div class="legend-content"><div class="legend-rail">Colors<br>Scheme<br>Combos</div><div><div class="legend-assembly">Stack · Differences · Remember</div><table><thead><tr><th>Layer</th><th>English<br><button type="button">System ▾</button></th><th><div class="legend-alt"><button type="button" aria-label="AltGr">R⎇</button></div></th><th><div class="legend-alt"><button type="button" aria-label="AltGr+Shift">⇧R⎇</button></div></th><th>Computer language<br><button type="button">Choose ▾</button></th></tr></thead><tbody><tr><th>default</th><td>e E</td><td>ˬ</td><td>ˬ</td><td></td></tr></tbody></table></div></div></div></div>`
