// Extract only used semantic roles from the app; the schematic has no parallel palette.
const appCss = await readFile(path.resolve(root, '../../../apps/web/src/app.css'), 'utf8')
const macroRoles = ['surface', 'surface-sunken', 'text', 'text-muted', 'text-disabled', 'border', 'border-subtle', 'accent', 'on-accent', 'danger-ink', 'danger-border', 'warn-ink', 'warn-wash', 'warn-border']
const roles = block => [...block.matchAll(/(--[\w-]+):\s*([^;]+);/g)].filter(([, name]) => macroRoles.includes(name.slice(2))).map(([, name, value]) => `${name}:${value};`).join('')
const macroCss = `
.macro-design{${roles(appCss.match(/:root \{([\s\S]*?)\n\}/)[1])}color-scheme:light;color:var(--text);background:var(--surface);padding:8px 10px;border-radius:8px;font-size:13px;line-height:1.4}
.macro-design .definition-panel{padding:8px 10px;border-radius:8px;background:var(--surface);color:var(--text);border-color:var(--border)}.macro-design .viewport-study{background:var(--surface-sunken);max-width:100%}.macro-design .definition-panel h2{font-size:18px}
@media(prefers-color-scheme:dark){.macro-design{${roles(appCss.match(/:root\[data-color-scheme="dark"\] \{([\s\S]*?)\n\}/)[1])}color-scheme:dark}}
.macro-design h2{font-size:18px;margin:0 0 6px}.macro-design h3{font-size:15px;margin:6px 0}.macro-design p{margin:6px 0;overflow-wrap:anywhere}.macro-design .columns{gap:8px}.macro-design .card{background:var(--surface);border:1px solid var(--border);padding:8px 10px;margin-bottom:8px}.macro-design .card h2{font-size:15px}.macro-design .macro-group{padding:7px 8px;border:1px solid var(--border-subtle);border-radius:6px;background:var(--surface-sunken);margin:6px 0}.macro-design .field,.macro-design pre{font:inherit;color:var(--text);background:var(--surface-sunken);border:1px solid var(--border);border-radius:4px;padding:2px 6px;margin:6px 0;overflow-wrap:anywhere;white-space:pre-wrap}.macro-design pre{font-family:monospace;padding:8px}.macro-design .actions{justify-content:flex-start;gap:4px;margin:6px 0}.macro-action{display:inline-flex;align-items:center;min-height:30px;padding:0 8px;border:1px solid var(--border);border-radius:6px;color:var(--text);background:var(--surface);font-size:13px}.macro-action.accent{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}.macro-action.danger{color:var(--danger-ink);border-color:var(--danger-border);background:transparent;font-weight:500}.macro-action.disabled{color:var(--text-disabled);border-color:var(--border-subtle);background:var(--surface-sunken)}.macro-design .notice{background:var(--warn-wash);border-color:var(--warn-border)}.macro-design .notice p{color:var(--warn-ink)}
.macro-design .field.disabled{color:var(--text-disabled);border-color:var(--border-subtle)}
@media(max-width:700px){body:has(.macro-design){padding:12px}body:has(.macro-design) .columns{grid-template-columns:minmax(0,1fr)}body:has(.macro-design) header{flex-wrap:wrap;gap:8px}body:has(.macro-design) .viewport-study{max-width:100%}body:has(.macro-design) .definition-panel{max-width:calc(100% - 32px)}body:has(.macro-design) .field{overflow-wrap:anywhere}}
`
const legendCss = `
.legend-profile-list li:not(.legend-menu-separator){margin:0}
.legend-menu-viewport{position:relative;width:360px;max-width:100%;height:640px;border:1px solid var(--border);background:var(--surface-sunken);font-size:12px}.legend-menu-context{position:absolute;top:20px;left:8px;right:8px;color:var(--text-muted)}.legend-menu-anchor{position:absolute;top:138px;right:8px;display:flex;flex-direction:column;gap:4px}.legend-menu-anchor button{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:4px;padding:3px 8px}.legend-menu-board{position:absolute;top:280px;left:8px;color:var(--text-muted)}.legend-profile-list{position:absolute;top:186px;right:8px;width:226px;max-height:calc(100% - 194px);overflow:auto;list-style:none;margin:0;padding:4px;border:1px solid var(--border);border-radius:6px;background:var(--surface)}.legend-profile-list li{display:flex;gap:2px;min-height:23px}.legend-profile-list button{font:inherit;color:var(--text);background:transparent;border:0;text-align:left;flex:1;min-width:0;padding:3px 8px;white-space:nowrap}.legend-profile-list button[aria-label]{flex:none;width:22px;padding:0;text-align:center;border:1px solid var(--border);border-radius:4px}.legend-profile-list .legend-menu-separator{min-height:1px;margin:4px;background:var(--border)}.legend-profile-list::-webkit-scrollbar{width:8px}.legend-profile-list::-webkit-scrollbar-thumb{background:var(--text-muted);border-radius:6px}
.legend-study{${roles(appCss.match(/:root \{([\s\S]*?)\n\}/)[1])}color-scheme:light;color:var(--text);background:var(--surface);padding:10px;border:1px solid var(--border);border-radius:8px;margin-bottom:20px;font-size:13px}
@media(prefers-color-scheme:dark){.legend-study{${roles(appCss.match(/:root\[data-color-scheme="dark"\] \{([\s\S]*?)\n\}/)[1])}color-scheme:dark}}
.legend-study h2{margin:0 0 6px}.legend-study p{margin:6px 0}.legend-examples{display:flex;flex-wrap:wrap;gap:20px}.legend-detail{width:360px;max-width:100%;min-width:0}.legend-scroll{overflow-x:auto;border:1px solid var(--border);background:var(--surface-sunken)}.legend-content{display:flex;align-items:flex-start;gap:10px;width:max-content;padding:4px}.legend-rail{width:80px;flex:none;line-height:26px;color:var(--text-muted)}.legend-assembly{height:28px;color:var(--text-muted)}.legend-content table{width:400px;border-collapse:collapse;white-space:nowrap;font-size:12px}.legend-content th,.legend-content td{padding:4px;border:1px solid var(--border);text-align:center;font-weight:500}.legend-content button{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--accent);border-radius:5px;padding:2px 6px;white-space:nowrap}.legend-alt{display:flex;align-items:center;justify-content:center;width:25px;height:54px}.legend-alt button{flex:none;transform:rotate(-90deg);border-radius:10px}.legend-study :focus-visible{outline:2px solid var(--accent);outline-offset:1px}
`
const unicodeCss = `
.unicode-study{${roles(appCss.match(/:root \{([\s\S]*?)\n\}/)[1])}color-scheme:light;font-size:12px;line-height:1.4;color:var(--text);background:var(--surface);padding:8px 10px;margin:16px 0;border-radius:8px}
@media(prefers-color-scheme:dark){.unicode-study{${roles(appCss.match(/:root\[data-color-scheme="dark"\] \{([\s\S]*?)\n\}/)[1])}color-scheme:dark}}
.unicode-study h2{font-size:15px;margin:0 0 6px}.unicode-study p{margin:6px 0;overflow-wrap:anywhere}.unicode-study .muted{color:var(--text-muted)}.unicode-study .columns{gap:8px}.unicode-study .columns>div{min-width:0}.unicode-study .card{padding:8px 10px;background:var(--surface);border-color:var(--border)}
.help-examples{display:flex;flex-wrap:wrap;gap:8px}.help-examples>div{flex:1 1 240px;min-width:0;padding:7px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface-sunken)}.behavior-help code{overflow-wrap:anywhere}.behavior-help .unicode-preview{flex-wrap:wrap}.behavior-help button{font-size:11px}.behavior-help button[title^="Studio Unlock"]{border-style:dashed}
.unicode-viewport{width:360px;max-width:100%;height:640px;margin:auto;padding:72px 11px 8px;background:var(--surface-sunken);border:1px solid var(--border)}.unicode-preview{display:flex;justify-content:center;align-items:center;gap:8px;min-height:48px;margin-bottom:12px}.unicode-main{max-height:496px;overflow-y:auto;padding:10px 14px 12px;background:var(--surface);border-radius:8px}.unicode-tabs{display:flex;gap:4px;flex-wrap:wrap;margin:6px 0}.unicode-study button{font:inherit;min-height:22px;padding:1px 7px;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:4px;overflow-wrap:anywhere}.unicode-study button[aria-pressed=true]{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,var(--surface))}.unicode-study :focus-visible{outline:2px solid var(--accent);outline-offset:1px}.unicode-study button:disabled{color:var(--text-disabled);background:var(--surface-sunken);border-color:var(--border-subtle)}
.unicode-fields{display:flex;flex-wrap:wrap;gap:6px}.unicode-study label{display:grid;gap:3px;flex:1 1 160px;min-width:0;color:var(--text-muted)}.unicode-study input,.unicode-study select{box-sizing:border-box;width:100%;min-width:0;height:24px;font:inherit;color:var(--text);background:var(--surface-sunken);border:1px solid var(--border);border-radius:4px;padding:0 6px}.unicode-study .unicode-alias{display:grid;gap:2px;padding:3px 6px;text-align:left;width:100%;margin-top:6px}.unicode-alias code{font-size:11px;overflow-wrap:anywhere}.unicode-status{padding:7px 8px;background:var(--surface-sunken);border:1px solid var(--border);border-radius:6px}.unicode-status.warning{color:var(--warn-ink);background:var(--warn-wash);border-color:var(--warn-border)}.unicode-error{color:var(--danger-ink)}
`
function html(title, body) {
  return `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escape(title)} · Keymap Editor</title><style>${css}${body.includes('class="layer-rows"') ? layerCss : ''}${body.includes('viewport-study') ? viewportCss : ''}${body.includes('class="macro-design"') ? macroCss : ''}${body.includes('class="legend-study"') ? legendCss : ''}${body.includes('class="unicode-study"') ? unicodeCss : ''}</style></head><body>${body}</body></html>\n`
}
await mkdir(path.join(root, 'html'), { recursive: true })
const manifest = { screens: screens.map(({ id, slug, title }) => ({
  id, title, html: `html/${id}-${slug}.html`, png: `exports/${id}-${slug}.png`,
  viewport: { width: 1440, height: id === 'CAP-001' ? 7500 : id === 'CAP-003' ? 3600 : 4900 }
})) }
for (const [index, screen] of screens.entries()) {
  const body = `<header><strong>Keymap Editor</strong><div class="chips">${chip('ZMK · firmware')}${chip('Host · OS layout')}</div><span class="eyebrow">${screen.id} · current surface</span></header><main><h1>${escape(screen.title)}</h1><p class="intro">${escape(screen.summary)}</p>${screen.body}</main><footer>Canonical schematic, not an application screenshot. Synthetic examples and separate example states. Current bounded behavior only; no proposed parity features are shown as shipped. <a href="../index.html">All capabilities</a></footer>`
  await writeFile(path.join(root, manifest.screens[index].html), html(screen.title, body))
}
await writeFile(path.join(root, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`)
await writeFile(path.join(root, 'index.html'), html('Current capability wireframes', `<main><h1>Current capability wireframes</h1><p>Generated schematics of implemented behavior, not future proposals or application screenshots.</p><ul>${manifest.screens.map(screen => `<li><a href="${screen.html}">${escape(screen.id)} — ${escape(screen.title)}</a> · <a href="${screen.png}">PNG</a></li>`).join('')}</ul></main>`))
console.log(`Generated ${manifest.screens.length} canonical capability screens.`)
